functions.boundedStyleCache:
function boundedStyleCache(limit) {
    var entries = new Map();
    return function(key, create) {
        if (entries.has(key)) return entries.get(key);
        var value = create();
        entries.set(key, value);
        if (entries.size > limit) entries.delete(entries.keys().next().value);
        return value;
    };
}

functions.refreshPortOverlay:
function refreshPortOverlay() {
    var records = layoutPortRecords.concat(factoryPortProjector.ports());
    var nextIds = new Set();
    records.forEach(function(port) {
        if (!Array.isArray(port.center) || !port.center.every(Number.isFinite) || nextIds.has(port.id)) return;
        nextIds.add(port.id);
        var feature = portFeatureById.get(port.id);
        if (feature) { feature.getGeometry().setCoordinates(port.center); feature.set('port', port); }
        else {
            feature = new ol.Feature({geometry:new ol.geom.Point(port.center)});
            feature.set('elementId', port.id);
            feature.set('port', port);
            feature.set('layer', Array.isArray(port.layer) ? port.layer.join('/') : String(port.layer || ''));
            feature.set('selected', false);
            feature.set('provenance', port.provenance || {});
            portFeatureById.set(port.id, feature);
            portSource.addFeature(feature);
        }
    });
    var removedSelected = false;
    for (var [id, feature] of portFeatureById) {
        if (nextIds.has(id)) continue;
        if (selectedFeatures.getArray().includes(feature)) { selectedFeatures.remove(feature); removedSelected = true; }
        portSource.removeFeature(feature);
        portFeatureById.delete(id);
    }
    document.getElementById('port-count').textContent = nextIds.size + ' port' + (nextIds.size === 1 ? '' : 's');
    if (removedSelected) onSelectionChanged();
}

functions.loadGdsData:
function loadGdsData(geojson, gdsPath, pythonFile, annotations, mode) {
    if(reviewTools)reviewTools.resetDocument(gdsPath);
    relatedOrderTargets=null;
    primitiveDraft=null;closeShapeMenu();closeCanvasContextMenu();
    // Preserve viewport on rebuild so user doesn't lose zoom/pan
    var isReload = allFeatures.length > 0;
    var prevCenter = isReload ? map.getView().getCenter() : null;
    var prevZoom = isReload ? map.getView().getZoom() : null;

    cancelFactoryPlacement();componentChooser.invalidateCache();factoryPreviewContext={};
    currentGdsPath = gdsPath;
    if(edaWorkbench)edaWorkbench.document(gdsPath);
    updateWorkOrderTargets();
    currentPythonFile = pythonFile || '';
    currentFilePath = gdsPath;
    currentMode2 = mode;
    attachSnapInteractions(false);
    try {
        // Snap has been detached above; fast clear cannot leave its old segments behind.
        // The layout source has no per-feature removal consumers (drawings do).
        source.clear(true);
        restoringAnnotations = true;
        drawSource.clear();
        selectedFeatures.clear();
        portSource.clear();
        portFeatureById.clear();
        layoutPortRecords = PortOverlay.layoutPorts(geojson);
        allFeatures = [];
        layerColors = {};
        featuresByLayer.clear();

        geojson.features.forEach(function(feature, index) {
            var props = feature.properties || {};
            var key = props.layer + '/' + props.data_type;
            layerColors[key] = props.color;
            var geom = gdsGeoJsonFmt.readGeometry(feature.geometry);
            var f = new ol.Feature({ geometry: geom });
            f.set('elementId', props.element_id || 'fixture-' + index);
            f.set('layer', key);
            f.set('color', props.color);
            f.set('layerKey', key);
            f.set('visible', true);
            f.set('selected', false);
            f.set('provenance', props.provenance || {});
            f.set('meta', {
                area_um2: props.area_um2,
                vertex_count: props.vertex_count,
                bbox: props.bbox || []
            });
            allFeatures.push(f);
            var layerFeatures=featuresByLayer.get(key);
            if(!layerFeatures){layerFeatures=[];featuresByLayer.set(key,layerFeatures);}
            layerFeatures.push(f);
        });
        source.addFeatures(allFeatures);

        // Recalculate map size before fitting — the map may have been
        // created before the webview container had its final dimensions.
        map.updateSize();

        if (allFeatures.length > 0 && isReload && prevCenter && prevZoom !== null) {
            map.getView().setCenter(prevCenter);
            map.getView().setZoom(prevZoom);
        } else if (allFeatures.length > 0) {
            var sz = map.getSize();
            if (sz && sz[0] >= 10 && sz[1] >= 10) {
                fitView();
            } else {
                _pendingFit = true;
            }
            // OpenLayers may not render features added while the canvas had
            // zero dimensions (common when the webview panel first appears).
            // Re-fit after the browser has painted the canvas.
            setTimeout(function() {
                map.updateSize();
                if(microLayer)fitMicroImage();else fitView();
            }, 200);
        }

        var invalidAnnotations = 0;
        (annotations || []).forEach(function(annotation) {
            try { drawSource.addFeature(featureFromSavedAnnotation(annotation)); } catch(e) { invalidAnnotations++; }
        });

        restoringAnnotations = false;
        refreshPortOverlay();
        var stale = drawSource.getFeatures().some(function(f){var i=f.get('intent');return i && i.snapshot && i.snapshot!==currentLayoutHash;});
        document.getElementById('workflow-status').textContent = stale ? 'Layout changed: review annotation targets.' : (allFeatures.length ? allFeatures.length + ' elements. Select, draw, then copy.' : 'This layout contains no visible geometry.');
        if (invalidAnnotations) document.getElementById('workflow-status').textContent += ' ' + invalidAnnotations + ' invalid annotation(s) could not be restored.';
        if (currentPythonFile) {
            vscode && vscode.postMessage({ type: 'viewerContext', pythonFile: currentPythonFile });
        }

        buildLegend();

        // Update provenance indicator (must be after buildLegend which recreates it)
        updateModeIndicator(mode);
    } finally {
        restoringAnnotations = false;
        attachSnapInteractions(snapActive);
    }
}

