function updateImageControls() {
    var panel=document.getElementById('image-controls');if(!panel)return;panel.hidden=!microImg||currentMode!=='select';
    var notice=document.getElementById('image-empty-notice');notice.hidden=!!microImg||!imageFeedback;notice.textContent=imageFeedback;
    document.getElementById('img-align-btn').disabled=!microImg||imageBusy;
    if(!microImg)return;
    var stack=document.getElementById('image-stack');stack.textContent='';
    microImages.slice().reverse().forEach(function(item){
        var row=document.createElement('div');row.className='image-stack-row';row.dataset.imageId=item.imageId;
        row.setAttribute('aria-current',String(item===microImg));
        var show=document.createElement('input');show.type='checkbox';show.checked=item.visible!==false;show.disabled=imageBusy;
        show.setAttribute('aria-label','Show '+item.name);
        show.onchange=function(){selectMicroImage(microImages.indexOf(item));item.visible=show.checked;renderMicroLayer();saveImageState();};
        var button=document.createElement('button');button.textContent=item.name;button.title=item.name;button.disabled=imageBusy;
        button.onclick=function(){selectMicroImage(microImages.indexOf(item));};
        var opacity=document.createElement('small');opacity.textContent=Math.round(item.opacity*100)+'%';
        row.append(show,button,opacity);stack.appendChild(row);
    });
    var display=Object.assign({},MicroscopeOverlay.defaultDisplay(),microImg.display||{});
    document.getElementById('image-display').value=display.mode;
    document.getElementById('image-border').checked=display.border;
    document.getElementById('image-contour-color').value=display.color;
    document.getElementById('image-contour-width').value=String(display.width);
    document.getElementById('image-contour-threshold').value=display.threshold;
    document.getElementById('image-contour-threshold-value').textContent=display.threshold;
    document.getElementById('image-contour-settings').hidden=display.mode==='image'&&!display.border;
    document.getElementById('image-contour-threshold').disabled=imageBusy||display.mode==='image';
    for(var control of ['image-display','image-border','image-contour-color','image-contour-width'])document.getElementById(control).disabled=imageBusy;
    var chooser=document.getElementById('image-select');chooser.textContent='';microImages.forEach(function(item,i){var option=document.createElement('option');option.value=String(i);option.textContent=(i+1)+'. '+item.name;chooser.appendChild(option);});chooser.value=String(microImages.indexOf(microImg));chooser.disabled=imageBusy;
    document.getElementById('image-lower').disabled=imageBusy||microImages.indexOf(microImg)<=0;
    document.getElementById('image-raise').disabled=imageBusy||microImages.indexOf(microImg)>=microImages.length-1;
    document.getElementById('image-place').disabled=imageBusy;
    var q=microImg.quality||{status:'unverified'},opts=microImg.options||MicroscopeOverlay.defaultOptions();
    document.getElementById('image-name').textContent=microImg.name;
    document.getElementById('image-name').title=microImg.name;
    document.getElementById('image-quality').textContent=imageBusy?'Matching numbered markers…':q.status==='aligned'?q.markerCount+' markers · '+q.boundaryRmsPx.toFixed(3)+' px RMS':q.status==='adjusted'?'Manually adjusted · align to recheck':'Not verified · align markers';
    document.getElementById('image-feedback').textContent=imageFeedback;
    document.getElementById('image-saved').textContent=imageSaveStatus;
    document.getElementById('image-visible').checked=microImg.visible!==false;
    document.getElementById('image-locked').checked=microImg.locked!==false;
    document.getElementById('image-opacity').value=Math.round(microImg.opacity*100);
    document.getElementById('image-opacity-value').textContent=Math.round(microImg.opacity*100)+'%';
    document.getElementById('image-appearance').value=opts.markerAppearance;
    if(document.activeElement!==document.getElementById('image-layers'))document.getElementById('image-layers').value=opts.markerLayers.join(',');
    document.getElementById('image-cancel').hidden=!imageBusy;
    for(var id of ['image-align','image-remove','image-appearance','image-layers'])document.getElementById(id).disabled=imageBusy;
    document.getElementById('image-reset').disabled=imageBusy||!microImg.markerPose;
    document.getElementById('img-move-btn').disabled=imageBusy||microImg.locked!==false;
}

