styles.vectorLayer:
function(feature) {
        if (feature.get('visible') === false) return hiddenVectorStyle;
        var selected = feature.get('selected');
        var labelText = feature.get('label');
        if (selected) {
            if (labelText) {
                return vectorStyleCache(JSON.stringify(['selected', labelText]), function(){return new ol.style.Style({
                    stroke: new ol.style.Stroke({ color: '#ffffff', width: 3 }),
                    fill: new ol.style.Fill({ color: 'rgba(255,255,255,0.3)' }),
                    text: new ol.style.Text({
                        text: labelText,
                        font: '10px monospace',
                        fill: new ol.style.Fill({ color: '#f9e2af' }),
                        stroke: new ol.style.Stroke({ color: '#1a1a2e', width: 2 })
                    })
                });});
            }
            return highlightStyle;
        }
        var color = feature.get('color') || '#fff';
        var visible = feature.get('visible') !== false;
        if (!visible) return hiddenVectorStyle;
        return vectorStyleCache(JSON.stringify(['normal', color, labelText || '']), function(){
            var style = new ol.style.Style({
                stroke: new ol.style.Stroke({ color: color, width: 1 }),
                fill: new ol.style.Fill({ color: color + '80' })
            });
            if (labelText) style.setText(new ol.style.Text({
                text: labelText,
                font: '10px monospace',
                fill: new ol.style.Fill({ color: '#f9e2af' }),
                stroke: new ol.style.Stroke({ color: '#1a1a2e', width: 2 })
            }));
            return style;
        });
    }

